#!/usr/bin/env node
/**
 * VIP commentary: margin notes through a book in the voice of a historical
 * thinker, generated by Claude and posted as ordinary public comments, so
 * readers can follow a book alongside them.
 *
 * How it fits the existing system — deliberately, with no schema changes:
 *
 * - Each persona is a real auth user (created here via the Admin API). The
 *   profile-sync trigger (sql-migrations/06) copies display_name from the
 *   user's metadata into profiles, so the annotations_with_users view and
 *   CommentsPanel render the persona's name with zero new columns.
 * - A comment is exactly what BookReader.addComment writes: type
 *   "highlight", a verbatim `data.quote` from the page (that's what lets
 *   "Show in the text" focus the passage), public visibility.
 * - What marks it VIP travels in `data` — `{ vip: true, persona, model }` —
 *   the same trick data.anonymous already uses, and CommentsPanel badges it.
 *
 * Honest labelling is non-negotiable: the UI shows "AI persona" on every one
 * of these. They are commentary written in a figure's VOICE, not words the
 * person wrote. Personas here are historical figures only — do not add
 * living people.
 *
 * Quotes are validated: a generated comment is dropped unless its quote is a
 * verbatim substring of the page it claims, so every posted comment anchors.
 *
 *   node scripts/generate-vip-comments.mjs --list-personas
 *   node scripts/generate-vip-comments.mjs --book "beyond good" --persona nietzsche --count 8 --dry-run
 *   node scripts/generate-vip-comments.mjs --book "beyond good" --persona nietzsche --count 8
 *   node scripts/generate-vip-comments.mjs --book "beyond good" --persona nietzsche --purge
 *
 * Needs ANTHROPIC_API_KEY, NEXT_PUBLIC_SUPABASE_URL and
 * SUPABASE_SERVICE_ROLE_KEY in .env.local.
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

// ---- Personas. Historical figures only — see the file comment. ----------

const PERSONAS = {
  nietzsche: {
    name: "Friedrich Nietzsche",
    voice:
      "Friedrich Nietzsche (1844-1900): aphoristic, combative, suspicious of " +
      "comfortable morality and of systems; delights in psychology, rank, " +
      "self-overcoming; scorns pity dressed as virtue; writes in short strikes " +
      "with occasional dark wit, never in academic hedges.",
  },
  aurelius: {
    name: "Marcus Aurelius",
    voice:
      "Marcus Aurelius (121-180): a Stoic emperor writing notes to himself; " +
      "measured, self-admonishing, concrete; returns everything to what is in " +
      "one's power, the shortness of life, duty to the common good; plain " +
      "sentences, no ornament, addressed as much to himself as to the reader.",
  },
  woolf: {
    name: "Virginia Woolf",
    voice:
      "Virginia Woolf (1882-1941): a novelist-critic's eye; attends to the " +
      "texture of consciousness, the small shifts of feeling under the scene, " +
      "what the sentence's rhythm is doing; generous but exact, capable of a " +
      "sudden cutting judgement; interested in what the author cannot see.",
  },
  dostoevsky: {
    name: "Fyodor Dostoevsky",
    voice:
      "Fyodor Dostoevsky (1821-1881): feverish moral seriousness; reads every " +
      "scene for the soul at stake in it; fascinated by pride, humiliation, " +
      "confession, grace breaking through squalor; argues with the text as if " +
      "the characters were alive and answerable.",
  },
  arendt: {
    name: "Hannah Arendt",
    voice:
      "Hannah Arendt (1906-1975): political theorist; reads for what a text " +
      "reveals about action, power, thoughtlessness and responsibility; " +
      "precise distinctions drawn calmly; wary of ideology in every costume; " +
      "long clear sentences that land somewhere unexpected.",
  },
};

// ---- Plumbing -----------------------------------------------------------

function readEnv() {
  const file = path.join(process.cwd(), ".env.local");
  if (!fs.existsSync(file)) throw new Error("No .env.local in this directory");
  const env = {};
  for (const line of fs.readFileSync(file, "utf8").split("\n")) {
    const i = line.indexOf("=");
    if (i === -1 || line.trim().startsWith("#")) continue;
    env[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  for (const k of ["NEXT_PUBLIC_SUPABASE_URL", "SUPABASE_SERVICE_ROLE_KEY"]) {
    if (!env[k]) throw new Error(`${k} missing from .env.local`);
  }
  return env;
}

const env = readEnv();
const SUPABASE_URL = env.NEXT_PUBLIC_SUPABASE_URL;
const AUTH = {
  apikey: env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,
};
const MODEL = "claude-sonnet-5";

const argv = process.argv.slice(2);
const flag = (name) => {
  const i = argv.indexOf(`--${name}`);
  return i !== -1 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : null;
};
const has = (name) => argv.includes(`--${name}`);

// Matches the naming in scripts/extract-books.mjs.
const slugify = (s) => (s || "book").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

async function findBook(query) {
  const res = await fetch(
    `${SUPABASE_URL}/rest/v1/books?select=id,title,author&title=ilike.*${encodeURIComponent(query)}*`,
    { headers: AUTH }
  );
  if (!res.ok) throw new Error(`Book lookup failed: ${res.status}`);
  const rows = await res.json();
  if (rows.length === 0) throw new Error(`No book matches "${query}"`);
  if (rows.length > 1)
    throw new Error(`"${query}" is ambiguous: ${rows.map((r) => r.title).join(" | ")}`);
  return rows[0];
}

async function loadText(title) {
  const res = await fetch(
    `${SUPABASE_URL}/storage/v1/object/texts/${slugify(title)}.json`,
    { headers: AUTH }
  );
  if (!res.ok)
    throw new Error(
      `No extracted text for "${title}" — run scripts/extract-books.mjs --upload first`
    );
  return res.json();
}

/**
 * The persona's auth user, created on first use. The email is an internal
 * marker address, unroutable on purpose; the password is random and thrown
 * away — nobody logs in as Nietzsche, rows are only ever written by this
 * script through the service role.
 */
async function ensurePersonaUser(slug, persona) {
  const email = `${slug}@vip-persona.internal`;

  const lookup = await fetch(
    `${SUPABASE_URL}/rest/v1/profiles?select=id,email&email=eq.${encodeURIComponent(email)}`,
    { headers: AUTH }
  );
  const existing = lookup.ok ? await lookup.json() : [];
  if (existing.length > 0) return existing[0].id;

  const res = await fetch(`${SUPABASE_URL}/auth/v1/admin/users`, {
    method: "POST",
    headers: { ...AUTH, "Content-Type": "application/json" },
    body: JSON.stringify({
      email,
      password: crypto.randomBytes(24).toString("base64url"),
      email_confirm: true,
      user_metadata: { display_name: persona.name },
    }),
  });
  if (!res.ok) throw new Error(`Creating persona user failed: ${res.status} ${await res.text()}`);
  const user = await res.json();
  console.log(`  created persona user ${persona.name} (${user.id})`);
  return user.id;
}

// ---- Generation ---------------------------------------------------------

/**
 * Pages sampled evenly through the body of the book (skipping front matter),
 * each carrying enough text to quote from.
 */
function samplePages(text, count) {
  const pages = (text.pages ?? []).filter(
    (p) => (p.paragraphs ?? []).join(" ").length > 400
  );
  const start = Math.min(Math.floor(pages.length * 0.08), 10);
  const usable = pages.slice(start);
  if (usable.length <= count) return usable;
  const picked = [];
  for (let i = 0; i < count; i++) {
    picked.push(usable[Math.floor((i + 0.5) * (usable.length / count))]);
  }
  return picked;
}

async function generateComments(book, persona, pages) {
  const { default: Anthropic } = await import("@anthropic-ai/sdk");
  const client = new Anthropic({ apiKey: env.ANTHROPIC_API_KEY });

  const pageBlocks = pages
    .map((p) => `<page number="${p.page}">\n${p.paragraphs.join("\n\n")}\n</page>`)
    .join("\n\n");

  const system =
    `You write margin commentary for a shared digital library, in the voice of a ` +
    `historical thinker, so readers can follow a book alongside them. The voice:\n\n` +
    `${persona.voice}\n\n` +
    `Rules:\n` +
    `- For each page provided, decide if there is a passage this thinker would genuinely ` +
    `seize on. Skip pages they would pass over; do not force one comment per page.\n` +
    `- "quote" must be copied VERBATIM from that page's text — an exact contiguous ` +
    `substring, 40 to 180 characters, no ellipses, no cleanup, no re-punctuation. The app ` +
    `anchors the comment to the page by string match; an inexact quote is discarded.\n` +
    `- "comment" is the thinker's marginal note on that passage: 1-3 sentences, in their ` +
    `voice, engaging the specific passage rather than summarising the book. Never break ` +
    `voice, never mention being an AI, never address the app.\n` +
    `- Vary the register: agreement, objection, amusement, a connection to their own ` +
    `thought. A margin is a conversation, not a lecture series.\n\n` +
    `Answer with ONLY a JSON array: [{"page": <number>, "quote": "...", "comment": "..."}]`;

  const message = await client.messages.create({
    model: MODEL,
    max_tokens: 4000,
    system,
    messages: [
      {
        role: "user",
        content:
          `The book is "${book.title}" by ${book.author}. ` +
          `Here are the pages:\n\n${pageBlocks}`,
      },
    ],
  });

  const raw = message.content
    .filter((b) => b.type === "text")
    .map((b) => b.text)
    .join("");
  const jsonText = raw.slice(raw.indexOf("["), raw.lastIndexOf("]") + 1);
  return JSON.parse(jsonText);
}

/** Only comments whose quote really is on their page survive. */
function validate(candidates, pages) {
  const byPage = new Map(pages.map((p) => [p.page, p.paragraphs.join("\n\n")]));
  const good = [];
  for (const c of candidates) {
    const text = byPage.get(c.page);
    if (!text || typeof c.quote !== "string" || typeof c.comment !== "string") continue;
    if (c.quote.length < 20 || !text.includes(c.quote)) {
      console.log(`  dropped (quote not verbatim on page ${c.page}): "${c.quote.slice(0, 60)}…"`);
      continue;
    }
    good.push(c);
  }
  return good;
}

async function insertComments(userId, bookId, personaSlug, comments) {
  const rows = comments.map((c) => ({
    user_id: userId,
    book_id: bookId,
    page_number: c.page,
    type: "highlight",
    data: {
      selectedText: c.quote,
      quote: c.quote,
      color: "#ffd97a",
      vip: true,
      persona: personaSlug,
      model: MODEL,
    },
    comment: c.comment,
    color: "#ffd97a",
    visibility: "public",
  }));
  const res = await fetch(`${SUPABASE_URL}/rest/v1/annotations`, {
    method: "POST",
    headers: { ...AUTH, "Content-Type": "application/json", Prefer: "return=minimal" },
    body: JSON.stringify(rows),
  });
  if (!res.ok) throw new Error(`Insert failed: ${res.status} ${await res.text()}`);
}

async function purge(userId, bookId) {
  const res = await fetch(
    `${SUPABASE_URL}/rest/v1/annotations?user_id=eq.${userId}&book_id=eq.${bookId}`,
    { method: "DELETE", headers: { ...AUTH, Prefer: "count=exact" } }
  );
  if (!res.ok) throw new Error(`Purge failed: ${res.status}`);
  console.log(`  purged ${res.headers.get("content-range")?.split("/")[1] ?? "?"} comment(s)`);
}

// ---- Main ---------------------------------------------------------------

async function main() {
  if (has("list-personas")) {
    for (const [slug, p] of Object.entries(PERSONAS)) console.log(`  ${slug.padEnd(12)} ${p.name}`);
    return;
  }

  const personaSlug = flag("persona");
  const bookQuery = flag("book");
  if (!personaSlug || !PERSONAS[personaSlug] || !bookQuery) {
    console.log(
      "Usage: node scripts/generate-vip-comments.mjs --book <title match> --persona <slug> " +
        "[--count 8] [--dry-run | --purge]\n       --list-personas to see the voices"
    );
    process.exitCode = 1;
    return;
  }
  const persona = PERSONAS[personaSlug];
  const count = Number(flag("count") ?? 8);

  const book = await findBook(bookQuery);
  console.log(`${persona.name} on "${book.title}" (${book.author})`);

  if (has("purge")) {
    const userId = await ensurePersonaUser(personaSlug, persona);
    await purge(userId, book.id);
    return;
  }

  // .env.local first, shell environment as a fallback.
  if (!env.ANTHROPIC_API_KEY) env.ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY ?? "";
  if (!env.ANTHROPIC_API_KEY)
    throw new Error(
      "ANTHROPIC_API_KEY is empty — paste your key into .env.local (console.anthropic.com → API Keys)"
    );

  const text = await loadText(book.title);
  const pages = samplePages(text, Math.max(count + 4, 10));
  console.log(`  sampling ${pages.length} pages of ${text.pageCount}`);

  const candidates = await generateComments(book, persona, pages);
  const comments = validate(candidates, pages).slice(0, count);
  console.log(`  ${comments.length} comment(s) survived quote validation`);

  for (const c of comments) {
    console.log(`\n  p.${String(c.page).padStart(3)} “${c.quote.slice(0, 70)}${c.quote.length > 70 ? "…" : ""}”`);
    console.log(`        ${c.comment}`);
  }

  if (has("dry-run")) {
    console.log("\nDry run — nothing written.");
    return;
  }

  const userId = await ensurePersonaUser(personaSlug, persona);
  await insertComments(userId, book.id, personaSlug, comments);
  console.log(`\nPosted ${comments.length} comment(s) as ${persona.name}.`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
